119								on:focus={() => handle_mouseover(ann.label)}
120								on:mouseout={() => handle_mouseout()}
121								on:blur={() => handle_mouseout()}
122								on:click={() => handle_click(i, ann.label)}
123							>
124								{ann.label}
125							</button>
126						{/each}
127					</div>
